import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.Cvf4Fkn6.js";const u=JSON.parse('{"title":"快捷键","description":"","frontmatter":{},"headers":[],"relativePath":"guide/hotkeys.md","filePath":"guide/hotkeys.md","lastUpdated":1794574960000}'),c={name:"guide/hotkeys.md"};function r(l,t,i,h,n,s){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h1><p>WTidy 的快捷键都挂在<strong>布局的区域</strong>上：按下即把前台窗口直接吸到该区域，跳过图标条。内置布局自带一套默认快捷键，开箱即用，也可以随时改录或清除。</p><h2 id="内置快捷键" tabindex="-1">内置快捷键 <a class="header-anchor" href="#内置快捷键" aria-label="Permalink to &quot;内置快捷键&quot;">​</a></h2><p>内置布局的每个区域都预置了快捷键，一律 <code>⌥⌘</code> 加一个键：</p><table tabindex="0"><thead><tr><th>布局</th><th>区域</th><th>快捷键</th></tr></thead><tbody><tr><td>左右半屏</td><td>左 / 右</td><td><code>⌥⌘←</code> / <code>⌥⌘→</code></td></tr><tr><td>上下半屏</td><td>上 / 下</td><td><code>⌥⌘↑</code> / <code>⌥⌘↓</code></td></tr><tr><td>三等分</td><td>左 / 中 / 右</td><td><code>⌥⌘[</code> / <code>⌥⌘\\</code> / <code>⌥⌘]</code></td></tr><tr><td>左 1/3 + 右 2/3</td><td>左 1/3 / 右 2/3</td><td><code>⌥⌘,</code> / <code>⌥⌘.</code></td></tr><tr><td>左 2/3 + 右 1/3</td><td>左 2/3 / 右 1/3</td><td><code>⌥⌘;</code> / <code>⌥⌘&#39;</code></td></tr><tr><td>四分</td><td>左上 / 右上 / 左下 / 右下</td><td><code>⌥⌘1</code> / <code>⌥⌘2</code> / <code>⌥⌘3</code> / <code>⌥⌘4</code></td></tr><tr><td>最大化</td><td>整屏</td><td><code>⌥⌘F</code></td></tr><tr><td>居中</td><td>中央区域</td><td><code>⌥⌘M</code></td></tr></tbody></table><p>这些快捷键显示在 <strong>设置 → 布局</strong> 各行的右侧。删除某个内置布局，它的快捷键随之失效；点「恢复内置布局」会连同默认快捷键一起恢复。</p><p>另有两个不属于任何布局的固定快捷键：</p><table tabindex="0"><thead><tr><th>动作</th><th>快捷键</th></tr></thead><tbody><tr><td>居中（保持窗口尺寸）</td><td><code>⌃⌥⌘C</code></td></tr><tr><td>恢复吸附前的位置</td><td><code>⌃⌥⌘Z</code></td></tr></tbody></table><blockquote><p>个别应用不发出拖拽通知（部分 Java / Electron 应用），拖拽分屏对它们无效——快捷键正好覆盖这个缺口。</p></blockquote><h2 id="改录与自定义" tabindex="-1">改录与自定义 <a class="header-anchor" href="#改录与自定义" aria-label="Permalink to &quot;改录与自定义&quot;">​</a></h2><p>内置布局和自己新建的布局用法相同：</p><ol><li>打开 <strong>设置 → 布局</strong>，找到目标布局行</li><li>点击区域对应的快捷键（未设置时显示「录制」），按下想用的组合</li><li>按 <code>Esc</code> 取消录制；点 <code>✕</code> 或按 <code>⌫</code> 清除</li></ol><p>一个快捷键由<strong>任意个修饰键（<code>⌃⌥⌘⇧</code>）加一个普通键</strong>组成，按住修饰键再按普通键即可，例如 <code>⌥←</code>、<code>⌥⌘L</code>、<code>⌃⌥⌘L</code>。两点限制：</p><ul><li>至少要有一个修饰键——单独一个字母会吞掉正常打字</li><li>不能只有修饰键（比如只按 <code>⌥⌘</code>）——系统的全局快捷键必须落在一个普通键上</li></ul><h2 id="冲突拦截" tabindex="-1">冲突拦截 <a class="header-anchor" href="#冲突拦截" aria-label="Permalink to &quot;冲突拦截&quot;">​</a></h2><p>录制时若组合已被占用（其他区域的快捷键、上面两个固定快捷键），会弹出冲突提示并显示占用者名称，换个组合即可。想把一个内置组合挪给别的区域，先清除原来的那个。</p><h2 id="快捷键不生效" tabindex="-1">快捷键不生效？ <a class="header-anchor" href="#快捷键不生效" aria-label="Permalink to &quot;快捷键不生效？&quot;">​</a></h2><ul><li>检查组合是否被其他应用的全局快捷键占用（如输入法、截图工具）</li><li>区域快捷键随布局删除一并失效</li><li>仍不工作请看<a href="./faq.html">常见问题</a>与日志 <code>~/Library/Logs/WTidy.log</code></li></ul>',18)])])}const b=d(c,[["render",r]]);export{u as __pageData,b as default};
